import migrationJournal from './meta/_journal.json';

interface MigrationJournal {
    dialect: string;
    entries: ReadonlyArray<{ idx: number; tag: string }>;
}

/**
 * Fails closed when the SQL bundled into the Server diverges from Drizzle's generated journal. Keeping this check at
 * module initialization makes an omitted, reordered, or duplicate manifest entry fail in tests and at startup instead
 * of silently splitting fresh and upgraded databases.
 */
export function assertMigrationManifestMatchesJournal(
    manifestTags: readonly string[],
    journal: MigrationJournal,
): void {
    const journalTags = journal.entries.map((entry) => entry.tag);
    const hasDuplicateManifestTag = new Set(manifestTags).size !== manifestTags.length;
    const hasDuplicateJournalTag = new Set(journalTags).size !== journalTags.length;
    const hasInvalidJournalIndex = journal.entries.some((entry, index) => entry.idx !== index);
    const hasDifferentOrder =
        manifestTags.length !== journalTags.length ||
        manifestTags.some((tag, index) => tag !== journalTags[index]);

    if (
        hasDuplicateManifestTag ||
        hasDuplicateJournalTag ||
        hasInvalidJournalIndex ||
        hasDifferentOrder ||
        journal.dialect !== 'sqlite'
    ) {
        throw new Error('Migration manifest does not match the generated Drizzle journal');
    }
}

